  --primary-foreground: hsl(300 50% 100%);
  --secondary: hsl(249.27 91.82% 93.71%);
  --secondary-foreground: hsl(249.15 32.57% 36.92%);
  --muted: hsl(239.92 36.34% 95.94%);
  --muted-foreground: hsl(240.18 13.08% 48.26%);
  --accent: hsl(218.46 99.9% 92.14%);
  --accent-foreground: hsl(240.33 28.88% 22.79%);
  --destructive: hsl(350.5 99.99% 67.13%);
  --destructive-foreground: hsl(300 50% 100%);
